-- 0001_init: generated by Chakram from app.spec.json. Additive changes go in new numbered files.
create table if not exists orgs (
  id text primary key,
  name text not null,
  created_at timestamptz not null default now()
);
create table if not exists users (
  id text primary key,
  org_id text not null references orgs(id),
  email text not null unique,
  name text not null,
  password_hash text not null,
  role text not null check (role in ('owner', 'member', 'viewer')),
  created_at timestamptz not null default now()
);
create table if not exists sessions (
  token text primary key,
  user_id text not null references users(id) on delete cascade,
  expires_at timestamptz not null
);
create index if not exists sessions_user_idx on sessions(user_id);

create table if not exists doctors (
  id text primary key,
  org_id text not null references orgs(id),
  name text not null,
  speciality text not null check (speciality in ('Cardiology', 'Dermatology', 'General')),
  email text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists doctors_org_idx on doctors(org_id);

create table if not exists appointments (
  id text primary key,
  org_id text not null references orgs(id),
  patient text not null,
  doctor text not null,
  start timestamptz not null,
  status text not null check (status in ('scheduled', 'done', 'cancelled')),
  fee double precision not null,
  notes text not null,
  paid boolean not null,
  satisfaction double precision not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists appointments_org_idx on appointments(org_id);
create index if not exists appointments_doctor_idx on appointments(doctor);

